import boto3,os
import json,urllib.request
iam=boto3.client("iam")
cfn=boto3.client("cloudformation")
def discover_role(name):
    # Only screen the initial scheduled lookup. A complete inventory omission
    # is not proof of deletion; final destroy and every known-role recheck use
    # GetRole directly. The rule stays enabled to discover future recreated labs.
    request={"MaxItems":1000}; seen=set(); found=[]
    for _ in range(20):
        page=iam.list_roles(**request)
        if (not isinstance(page.get("Roles"),list) or type(page.get("IsTruncated")) is not bool
            or any(not isinstance(role,dict) or not isinstance(role.get("RoleName"),str)
                or not isinstance(role.get("RoleId"),str) or not role["RoleId"] for role in page["Roles"])):
            raise RuntimeError("Invalid IAM role inventory")
        found.extend(role for role in page["Roles"] if role.get("RoleName")==name)
        if not page["IsTruncated"]:
            if page.get("Marker"): raise RuntimeError("Unexpected final IAM inventory marker")
            if len(found)>1 or (found and not found[0].get("RoleId")):
                raise RuntimeError("Ambiguous IAM role inventory")
            return found[0]["RoleId"] if found else None
        marker=page.get("Marker")
        if not isinstance(marker,str) or not marker or marker in seen:
            raise RuntimeError("Incomplete IAM role inventory")
        seen.add(marker); request["Marker"]=marker
    raise RuntimeError("IAM role inventory exceeded its pagination bound")
def owned_role(name,identity=None):
    role=iam.get_role(RoleName=name)["Role"]
    if not role.get("RoleId") or (identity is not None and role["RoleId"]!=identity):
        raise RuntimeError("Final cleanup role identity changed")
    return role
def stable_role(role):
    stable={key:value for key,value in role.items() if key not in ("Tags","RoleLastUsed")}
    tags=role.get("Tags",[])
    stable["Tags"]={item["Key"]:item["Value"] for item in tags}
    if len(tags)!=len(stable["Tags"]): raise RuntimeError("Ambiguous role tags")
    return stable
def remove_retired_role(initial_inventory):
    name=os.environ["TARGET_ROLE"]
    identity=discover_role(name) if initial_inventory else None
    if initial_inventory and identity is None:
        return {"status":"role not listed; no action"}
    try:
        role=owned_role(name,identity)
    except iam.exceptions.NoSuchEntityException:
        return {"status":"role already removed"}
    tags={item["Key"]:item["Value"] for item in role.get("Tags",[])}
    stack_id=tags.get("BudgetStack","")
    expected=os.environ["TARGET_STACK"]
    parts=stack_id.split(":",5)
    if (role.get("RoleName")!=name or tags.get("DeploymentGuide")!="FortiAIGate-GPU-AWS-v1"
        or tags.get("BudgetVersion")!="8h-delete-v2" or len(parts)!=6
        or parts[4]!=os.environ["ACCOUNT_ID"] or parts[3]!=os.environ["REGION"]
        or parts[5].split("/")[:2]!=["stack",expected]):
        raise RuntimeError("Final cleanup ownership check failed")
    identity=role["RoleId"]
    def recheck():
        current=owned_role(name,identity)
        if stable_role(current)!=stable_role(role):
            raise RuntimeError("Final cleanup role changed after ownership verification")
    try:
        stacks=cfn.describe_stacks(StackName=stack_id)["Stacks"]
        if len(stacks)!=1 or stacks[0].get("StackId")!=stack_id:
            raise RuntimeError("Final cleanup stack identity changed")
        if stacks[0]["StackStatus"]!="DELETE_COMPLETE":
            return {"status":"stack still exists; role retained"}
    except cfn.exceptions.ClientError as error:
        if (error.response.get("Error",{}).get("Code")!="ValidationError"
            or "does not exist" not in error.response.get("Error",{}).get("Message","")):
            raise
    profiles=iam.list_instance_profiles_for_role(RoleName=name)
    attached=iam.list_attached_role_policies(RoleName=name)
    policies=iam.list_role_policies(RoleName=name)
    if (profiles.get("InstanceProfiles") or profiles.get("IsTruncated") or attached.get("AttachedPolicies")
        or attached.get("IsTruncated") or policies.get("IsTruncated")
        or policies.get("PolicyNames") not in ([],["DeleteOnlyThisLab"])):
        raise RuntimeError("Final cleanup found unexpected role permissions or profiles")
    for policy in policies["PolicyNames"]:
        recheck()
        iam.delete_role_policy(RoleName=name,PolicyName=policy)
    recheck()
    iam.delete_role(RoleName=name)
    try:
        owned_role(name,identity)
    except iam.exceptions.NoSuchEntityException:
        return {"status":"retired exact lab cleanup role removed"}
    raise RuntimeError("Final cleanup role deletion is not yet verified")
def cleanup(initial_inventory=True):
    try:
        return remove_retired_role(initial_inventory)
    except iam.exceptions.NoSuchEntityException:
        # Another invocation may have deleted a policy/role. Missing policy or
        # membership alone is not proof that the positively identified role is
        # gone; confirm directly, never substitute an inventory omission.
        try:
            iam.get_role(RoleName=os.environ["TARGET_ROLE"])
        except iam.exceptions.NoSuchEntityException:
            return {"status":"role already removed"}
        raise RuntimeError("Cleanup raced with a change while the target role still exists")
def respond(event,status):
    body=json.dumps({"Status":status,"Reason":"Exact GPU cleanup role ownership and deletion verification",
        "PhysicalResourceId":event.get("PhysicalResourceId",event["LogicalResourceId"]),
        "StackId":event["StackId"],"RequestId":event["RequestId"],"LogicalResourceId":event["LogicalResourceId"],
        "Data":{}}).encode()
    request=urllib.request.Request(event["ResponseURL"],data=body,method="PUT",
        headers={"content-type":"","content-length":str(len(body))})
    with urllib.request.urlopen(request,timeout=15) as response:
        response.read()
def handler(event,context):
    if "RequestType" not in event:
        return cleanup()
    status="SUCCESS"
    try:
        if event["RequestType"]=="Delete":
            result=cleanup(initial_inventory=False)
            if result["status"] not in ("role already removed","retired exact lab cleanup role removed"):
                raise RuntimeError("GPU lab still exists; final cleanup service retained")
        elif event["RequestType"] not in ("Create","Update"):
            raise RuntimeError("Unknown final cleanup lifecycle request")
    except Exception:
        status="FAILED"
    respond(event,status)
    return {"status":status}
